import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"WebAuthn Passkey Dogfood — caBLE hybrid transport quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/webauthn-passkey-app-cable.md","filePath":"quality-reports/auth/webauthn-passkey-app-cable.md"}'),r={name:"quality-reports/auth/webauthn-passkey-app-cable.md"};function o(n,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="webauthn-passkey-dogfood-—-cable-hybrid-transport-quality-report" tabindex="-1">WebAuthn Passkey Dogfood — caBLE hybrid transport quality report <a class="header-anchor" href="#webauthn-passkey-dogfood-—-cable-hybrid-transport-quality-report" aria-label="Permalink to &quot;WebAuthn Passkey Dogfood — caBLE hybrid transport quality report&quot;">​</a></h1><p>Report for <code>examples/dogfood-webauthn-passkey-app</code> GH #890 (v1.22-4). Adds the caBLE hybrid transport (CTAP2) axes on top of the register / signin / userVerification / residentKey fidelity work v1.21-2 landed.</p><h2 id="fidelity-axes-cable-hybrid-transport-5-軸" tabindex="-1">Fidelity axes (caBLE hybrid transport, 5 軸) <a class="header-anchor" href="#fidelity-axes-cable-hybrid-transport-5-軸" aria-label="Permalink to &quot;Fidelity axes (caBLE hybrid transport, 5 軸)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-test/auth</code> caBLE surface)</th><th>real (real phone + real BLE + real WebSocket tunnel)</th><th>assertion</th></tr></thead><tbody><tr><td>1. QR code generation</td><td><code>FIDO:/&lt;sessionId&gt;?pubkey=&lt;tagged&gt;&amp;tunnel=&lt;hint&gt;&amp;nonce=&lt;nonce&gt;</code> — deterministic session id counter, credential id tag embedded in pubkey</td><td><code>FIDO:/</code> URI carrying base32-encoded EC P-256 public key + tunnel server hint + random nonce</td><td>Both encode as a <code>FIDO:/</code> URI. Mock keeps the pubkey / tunnel / nonce as literal strings so structural drift is caught; real produces base32 payload but the URI shape + field ordering is identical.</td></tr><tr><td>2. BLE advertisement handshake</td><td>deterministic shared secret <code>shared-secret::&lt;sessionId&gt;::&lt;nonce&gt;</code> — both sides derive matching values, verified=true</td><td>ECDH between ephemeral P-256 keys, nonce as KDF salt, 20-byte encrypted advertisement</td><td>Mock verifies that shared secret derivation is stable across the initiator + responder + binds to nonce. Real advertisement payload is opaque bytes; mock keeps <code>ble-adv::&lt;sessionId&gt;::&lt;len&gt;</code> so the correlation key survives to the tunnel step.</td></tr><tr><td>3. WebSocket tunnel establishment</td><td>in-memory FIFO with session id + tunnel hint carried over from QR, FIFO drain, close/reject lifecycle</td><td>duplex WebSocket over tunnel server, protected by BLE handshake shared secret</td><td>Both fail the tunnel open when the handshake did not verify. Both preserve message order (FIFO). Mock rejects send / drain after close; real closes the socket + fails subsequent frames.</td></tr><tr><td>4. Credential migration payload</td><td><code>enc::&lt;sessionId&gt;::&lt;credentialId&gt;::&lt;userId&gt;</code> tagged string, appended to tunnel wire log</td><td>encrypted <code>PasskeyCredential</code> blob shipped over the tunnel</td><td>Both bind the migration payload to the session id + credential id + user id so cross-session leak is impossible. Mock preserves the credential object verbatim on the initiator side so the fidelity harness can inspect the resulting shape without cracking encryption.</td></tr><tr><td>5. Signature roundtrip</td><td><code>sig::&lt;credentialId&gt;::&lt;challenge&gt;::&lt;sessionId&gt;</code> signature over WebAuthn L3 §7.2 assertion, verified=true</td><td>ES256 / EdDSA signature over the client data JSON + authenticator data</td><td>Both refuse an empty challenge (WebAuthn L3 §7.2). Both bind signature to credential id so cross-credential assertion is impossible. Mock preserves the challenge input verbatim in the signature tag for wire-log inspection; real signature bytes are opaque but the initiator-side verification path is identical.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>packages/auth/tests/setup-passkey-cable-env.test.ts</code> — 24 tests split into six describe blocks: <ul><li><code>caBLE fidelity axis 1 — QR code generation</code> — 5 tests covering session id counter + credential tagging + tunnel hint + nonce + <code>FIDO:/</code> URI shape + empty tunnel / nonce rejection + per-session public key freshness</li><li><code>caBLE fidelity axis 2 — BLE advertisement handshake</code> — 4 tests covering shared secret derivation + advertisement payload embedding + empty session id rejection + nonce binding</li><li><code>caBLE fidelity axis 3 — WebSocket tunnel establishment</code> — 5 tests covering session id + tunnel hint carryover + FIFO drain semantics + handshake-not-verified refusal + session id mismatch refusal + close lifecycle</li><li><code>caBLE fidelity axis 4 — credential migration payload</code> — 3 tests covering encrypted payload shape + wire log recording + closed tunnel refusal</li><li><code>caBLE fidelity axis 5 — signature roundtrip</code> — 4 tests covering signature tag shape + tunnel wire log ordering (migration → signature) + empty challenge refusal + closed tunnel refusal</li><li><code>caBLE end-to-end ceremony — runCaBLESession chains every step</code> — 3 tests covering step completion order + credential id consistency migration→signature + per-session artifact independence</li></ul></li><li><code>examples/dogfood-webauthn-passkey-app/tests/passkey-cable.spec.ts</code> — 16 tests exercising the same five axes end-to-end from the dogfood app boundary, plus the <code>runCaBLESession</code> chain assertion + replay-impossibility check.</li></ul><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — mock caBLE surface always runs (pure in-memory simulation, no BLE stack or tunnel server needed).</li><li>Real caBLE hybrid transport (real phone + BLE advertisement + WebSocket tunnel server) is out of scope for <code>pnpm test</code> / <code>pnpm test:e2e</code> on developer machines — the fidelity harness proves the wire-format assertions the real path would satisfy without driving a real Bluetooth stack.</li><li>Chrome <code>--enable-features=WebAuthenticationRemoteDesktopSupport</code> flag is experimental at the time of v1.22-4 land — the mock covers every wire-format axis the real path exposes; a future revision can add a Playwright real-device harness once the flag stabilizes.</li></ul><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Real device caBLE walkthrough — once Chrome ships stable hybrid transport support, add a <code>tests/e2e/passkey-cable-real.spec.ts</code> that drives a real Chrome Virtual Authenticator over a locally-run tunnel server. The fidelity axes stay stable; only the driver changes.</li><li>Federation JWKS rotation real e2e (GH #891, v1.22-5) — uses the caBLE credential migration payload as a signal that a passkey survived cross-device sync during rotation.</li><li>v1.22-6 release publish — the caBLE fidelity axes feed into the release gate 7 軸 pass count alongside the register / signin / uv / residentKey axes.</li></ul>',10)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
